public class OrderService {
    public String getCustomerName(Order order) {
        // BAD: will throw NPE if order is null
        // return order.getCustomer().getName();

        // BETTER: null checks
        if (order != null && order.getCustomer() != null) {
            return order.getCustomer().getName();
        }
        return "Unknown";
    }

    // BEST: use Optional to make nullability explicit
    public Optional<String> getCustomerNameSafe(Order order) {
        return Optional.ofNullable(order)
                .map(Order::getCustomer)  // returns Optional<Customer>
                .map(Customer::getName);  // returns Optional<String>
    }

    public void processOrder(Long orderId) {
        var orderOpt = orderRepository.findById(orderId);  // returns Optional<Order>
        orderOpt.ifPresent(order -> {
            System.out.println("Processing: " + order.getItem());
        });
    }
}

public class ArrayDemo {
    public void processOrders(String[] orders) {
        // BAD: off-by-one error
        // for (int i = 0; i <= orders.length; i++) {
        //     System.out.println(orders[i]);  // throws exception on last iteration
        // }

        // GOOD: correct boundary
        for (int i = 0; i < orders.length; i++) {
            System.out.println(orders[i]);
        }

        // BETTER: enhanced for-loop avoids indexing entirely
        for (var order : orders) {
            System.out.println(order);
        }
    }

    public String getLastOrder(String[] orders) {
        if (orders.length == 0) {
            return "No orders";  // handle empty array
        }
        return orders[orders.length - 1];  // last valid index
    }

    // BEST: use List instead of array
    public void processOrderList(List<String> orders) {
        orders.forEach(System.out::println);  // no index needed
    }
}

public class CastingDemo {
    public void processData(Object data) {
        // BAD: unsafe cast without checking
        // String text = (String) data;  // throws ClassCastException if data is not a String

        // GOOD: check type before casting
        if (data instanceof String text) {  // Java 17 pattern matching
            System.out.println("Text: " + text.toUpperCase());
        } else if (data instanceof Integer number) {
            System.out.println("Number: " + number * 2);
        }
    }

    // Example with collections
    public void oldStyleCollection() {
        List rawList = new ArrayList();  // raw type, no generics
        rawList.add("Hello");
        rawList.add(123);

        // This throws ClassCastException on second element
        // for (Object obj : rawList) {
        //     String text = (String) obj;
        // }
    }

    // MODERN: generics prevent ClassCastException at compile time
    public void modernCollection() {
        List<String> texts = List.of("Hello", "World");
        // texts.add(123);  // compile error — type safety
        texts.forEach(System.out::println);  // no casting needed
    }
}

@RestController
public class OrderController {

    // BAD: lets NumberFormatException become 500 error
    // @GetMapping("/orders/{id}")
    // public Order getOrder(@PathVariable String id) {
    //     Long orderId = Long.parseLong(id);  // throws if id is "abc"
    //     return orderService.findById(orderId);
    // }

    // GOOD: handle parsing error explicitly
    @GetMapping("/orders/{id}")
    public ResponseEntity<?> getOrder(@PathVariable String id) {
        try {
            var orderId = Long.parseLong(id.trim());
            var order = orderService.findById(orderId);
            return ResponseEntity.ok(order);
        } catch (NumberFormatException e) {
            return ResponseEntity.badRequest()
                .body("Invalid order ID: must be a number");
        }
    }

    // BETTER: use path variable type conversion
    @GetMapping("/orders/{id}")
    public Order getOrderTypeSafe(@PathVariable Long id) {  // Spring converts automatically
        return orderService.findById(id);
    }
}

public class CollectionModDemo {

    public void removeInactiveUsers(List<User> users) {
        // BAD: throws ConcurrentModificationException
        // for (User user : users) {
        //     if (!user.isActive()) {
        //         users.remove(user);  // modifies collection during iteration
        //     }
        // }

        // GOOD: use Iterator.remove()
        var iterator = users.iterator();
        while (iterator.hasNext()) {
            var user = iterator.next();
            if (!user.isActive()) {
                iterator.remove();  // safe removal through iterator
            }
        }
    }

    // BEST: use removeIf with predicate (Java 8+)
    public void removeInactiveUsersModern(List<User> users) {
        users.removeIf(user -> !user.isActive());
    }

    // Alternative: collect then remove
    public void removeWithStream(List<User> users) {
        var toRemove = users.stream()
            .filter(user -> !user.isActive())
            .toList();
        users.removeAll(toRemove);
    }
}

// Simple unchecked exception for domain errors
public class OrderNotFoundException extends RuntimeException {
    public OrderNotFoundException(String message) {
        super(message);  // pass message to parent
    }
}

// More advanced: include entity ID for debugging
public class InsufficientStockException extends RuntimeException {
    private final String productId;
    private final int requestedQuantity;

    public InsufficientStockException(String productId, int requested) {
        super("Insufficient stock for product " + productId + 
              ": requested " + requested);
        this.productId = productId;
        this.requestedQuantity = requested;
    }

    public String getProductId() { return productId; }
}

// Usage in service layer
@Service
public class OrderService {
    public Order getOrder(Long orderId) {
        return orderRepository.findById(orderId)
            .orElseThrow(() -> new OrderNotFoundException(
                "Order with ID " + orderId + " not found"));
    }
}

public class ResourceDemo {

    // OLD STYLE: manual cleanup with finally
    public String readFileOldWay(String path) throws IOException {
        BufferedReader reader = null;
        try {
            reader = new BufferedReader(new FileReader(path));
            return reader.readLine();
        } catch (IOException e) {
            System.err.println("Error reading file: " + e.getMessage());
            throw e;  // finally still runs before exception propagates
        } finally {
            if (reader != null) {
                reader.close();  // guaranteed to execute
            }
        }
    }

    // MODERN: try-with-resources (Java 7+)
    public String readFileModern(String path) throws IOException {
        try (var reader = new BufferedReader(new FileReader(path))) {
            return reader.readLine();
        }  // reader.close() called automatically, even on exception
    }

    // Finally for non-resource cleanup
    public void processOrder(Order order) {
        try {
            orderService.validate(order);
            orderService.save(order);
        } finally {
            auditLog.log("Order processing attempted for: " + order.getId());
        }
    }
}
